    instDiscs: { en: "Game discs", es: "Discos del juego", pt: "Discos do jogo" },
    instDiscsDesc: { en: "Add your God of War ISO. One is enough; with several (e.g. the original and a translation) each language becomes playable and the game asks which one you want.", es: "Añade tu ISO de God of War. Con una basta; con varias (p. ej. la original y una traducción) cada idioma queda jugable y el juego pregunta cuál quieres.", pt: "Adicione sua ISO do God of War. Uma basta; com várias (ex.: a original e uma tradução) cada idioma fica jogável e o jogo pergunta qual você quer." },
    instAddIso: { en: "Add ISO…", es: "Añadir ISO…", pt: "Adicionar ISO…" },
    instClearIso: { en: "Clear list", es: "Vaciar lista", pt: "Limpar lista" },
    instPickIso: { en: "Choose disc images", es: "Elige imágenes de disco", pt: "Escolha as imagens de disco" },
    instQuality_original: { en: "original disc", es: "disco original", pt: "disco original" },
    instQuality_full: { en: "translation on the original disc", es: "traducción sobre el disco original", pt: "tradução sobre o disco original" },
    instQuality_standalone: { en: "translation disc only (4:3 movies)", es: "solo el disco traducido (vídeos 4:3)", pt: "só o disco traduzido (vídeos 4:3)" },
    instBuild: { en: "Build", es: "Compilación", pt: "Compilação" },
    instOptimize: { en: "Optimize for 60 fps", es: "Optimizar para 60 fps", pt: "Otimizar para 60 fps" },
    instOptimizeDesc: { en: "After the build the game plays itself for 4 minutes, hidden in the background, to record the code it uses, then compiles it natively. While you play, new code is recorded too: \"Speed up visited areas\" compiles it.", es: "Tras compilar, el juego se juega solo 4 minutos, oculto en segundo plano, para grabar el código que usa y lo compila de forma nativa. Mientras juegas también se graba código nuevo: «Acelerar zonas visitadas» lo compila.", pt: "Depois de compilar, o jogo se joga sozinho por 4 minutos, escondido em segundo plano, para gravar o código que usa e o compila de forma nativa. Enquanto você joga, código novo também é gravado: \"Acelerar áreas visitadas\" o compila." },
    instInstall: { en: "Install and build", es: "Instalar y compilar", pt: "Instalar e compilar" },
