    perfilDesc: { tr: "Aşağıdaki ayarları tek seferde seçer. Oyunda F1 ile canlı ayarlanabilir.", en: "Sets the options below in one go. F1 in game adjusts them live.", es: "Ajusta las opciones de abajo de una vez. F1 en el juego las cambia en vivo.", pt: "Ajusta as opções abaixo de uma vez. F1 no jogo muda tudo ao vivo." },
    perfilDesempenho: { tr: "Performans", en: "Performance", es: "Rendimiento", pt: "Desempenho" },
    perfilDesempenhoDet: { tr: "1× çözünürlük, zayıf GPU'lar için", en: "1× resolution, for weak GPUs", es: "Resolución 1×, para GPU modestas", pt: "Resolução 1×, para GPUs fracas" },
    perfilEquilibrado: { tr: "Dengeli", en: "Balanced", es: "Equilibrado", pt: "Equilibrado" },
    perfilEquilibradoDet: { tr: "2×, keskin filtre, FXAA (önerilen)", en: "2×, sharp filter, FXAA (recommended)", es: "2×, filtro nítido, FXAA (recomendado)", pt: "2×, filtro nítido, FXAA (recomendado)" },
    perfilQualidade: { tr: "Kalite", en: "Quality", es: "Calidad", pt: "Qualidade" },
    perfilQualidadeDet: { tr: "Ekrana göre otomatik, 16× anizotropik", en: "Automatic for your screen, 16× anisotropic", es: "Automática para tu pantalla, anisotrópico 16×", pt: "Automática para sua tela, anisotrópico 16×" },
    perfilPersonalizado: { tr: "Özel", en: "Custom", es: "Personalizado", pt: "Personalizado" },
    perfilPersonalizadoDet: { tr: "Aşağıda değiştirildi", en: "changed below", es: "cambiado abajo", pt: "alterado abaixo" },
    grupoImagen: { tr: "GÖRÜNTÜ", en: "IMAGE", es: "IMAGEN", pt: "IMAGEM" },
    grupoCalidad: { tr: "KALİTE", en: "QUALITY", es: "CALIDAD", pt: "QUALIDADE" },
    grupoHerramientas: { tr: "ÖLÇEKLEME VE ARAÇLAR", en: "UPSCALING AND TOOLS", es: "ESCALADO Y HERRAMIENTAS", pt: "UPSCALING E FERRAMENTAS" },
    upNativo: { tr: "Yerleşik ölçekleme", en: "Built-in upscaling", es: "Escalado integrado", pt: "Upscaling nativo" },
    upNativoDesc: { tr: "Oyun, iç çözünürlükte gerçekten daha fazla piksel çizer (2×, 3×…); keskin filtre ve FXAA sonra ekrana uydurur. GPU ağırsa iç çözünürlüğü düşürmek FPS kazandırır; CPU sınırlı sahnelerde değişmez.", en: "The game really draws more pixels at the internal resolution (2×, 3×…); the sharp filter and FXAA then fit it to your screen. Lowering the internal resolution gains FPS when the GPU is the limit; it does not help CPU-bound scenes.", es: "El juego dibuja de verdad más píxeles a la resolución interna (2×, 3×…); el filtro nítido y el FXAA la ajustan a tu pantalla. Bajar la resolución interna da FPS si la GPU es el límite; no ayuda en escenas limitadas por la CPU.", pt: "O jogo desenha de verdade mais pixels na resolução interna (2×, 3×…); o filtro nítido e o FXAA ajustam à sua tela. Baixar a resolução interna dá FPS quando a GPU é o limite; não ajuda em cenas limitadas pela CPU." },
    upDlss: { tr: "DLSS / FSR 2–3 / XeSS", en: "DLSS / FSR 2–3 / XeSS", es: "DLSS / FSR 2–3 / XeSS", pt: "DLSS / FSR 2–3 / XeSS" },
    upDlssDesc: { tr: "Kullanılamaz: hareket vektörleri ve DirectX 12/Vulkan ister; PS2 grafik birimi (OpenGL) bunları vermez. Yerine yerleşik ölçeklemeyi kullanın.", en: "Not available: they need motion vectors and DirectX 12/Vulkan; the PS2 graphics unit (OpenGL here) provides neither. Use the built-in upscaling instead.", es: "No disponible: necesitan vectores de movimiento y DirectX 12/Vulkan; la unidad gráfica del PS2 (aquí OpenGL) no los da. Usa el escalado integrado.", pt: "Indisponível: exigem vetores de movimento e DirectX 12/Vulkan; a unidade gráfica do PS2 (aqui em OpenGL) não fornece isso. Use o upscaling nativo." },
    upNoDisponible: { tr: "Yok", en: "Not available", es: "No disponible", pt: "Indisponível" },
    upExternas: { tr: "Harici araçlara izin ver", en: "Allow external tools", es: "Permitir herramientas externas", pt: "Permitir ferramentas externas" },
    upExternasDesc: { tr: "Lossless Scaling (ölçekleme / kare üretimi), ReShade (OpenGL) ve OBS kenarsız pencereyi görür: açıkken görüntü modu kenarsız olur. Bu araçlar resmi olarak test edilmedi; gecikme ekleyebilirler.", en: "Lossless Scaling (scaling / frame generation), ReShade (OpenGL) and OBS see a borderless window: on, the display mode becomes borderless. These tools are not officially tested and may add latency.", es: "Lossless Scaling (escalado / generación de fotogramas), ReShade (OpenGL) y OBS ven una ventana sin bordes: activado, el modo de pantalla pasa a sin bordes. No están probadas oficialmente y pueden añadir retraso.", pt: "Lossless Scaling (escala / geração de quadros), ReShade (OpenGL) e OBS enxergam a janela sem bordas: ligado, o modo de exibição vira sem bordas. Essas ferramentas não são testadas oficialmente e podem adicionar atraso." },
    cardPerfil: { tr: "Grafik profili", en: "Graphics profile", es: "Perfil gráfico", pt: "Perfil gráfico" },
    cardControles: { tr: "Kontroller", en: "Controls", es: "Controles", pt: "Controles" },
    cardMando: { tr: "Kumanda", en: "Controller", es: "Mando", pt: "Controle" },
    cardTeclado: { tr: "Klavye ve fare", en: "Keyboard and mouse", es: "Teclado y ratón", pt: "Teclado e mouse" },
    cardTecladoDet: { tr: "tuşlar Kontroller sayfasında", en: "keys on the Controls page", es: "teclas en la página Controles", pt: "teclas na página Controles" },
    pistaF1: { tr: "Oyunda F1: grafikler, hileler ve kayıt", en: "In game, F1: graphics, cheats and save", es: "En el juego, F1: gráficos, trucos y partida", pt: "No jogo, F1: gráficos, truques e save" },
    tecladoAtajo: { tr: "Klavye ve fareyle oyna", en: "Play with keyboard and mouse", es: "Jugar con teclado y ratón", pt: "Jogar no teclado e mouse" },
    tecladoAtajoDesc: { tr: "Kumanda bulunamadı: WASD hareket, fare tuşları saldırı, Boşluk zıplama. Tüm tuşlar değiştirilebilir.", en: "No controller found: WASD moves, mouse buttons attack, Space jumps. Every key can be changed.", es: "No hay mando: WASD mueve, botones del ratón atacan, Espacio salta. Todas las teclas se pueden cambiar.", pt: "Nenhum controle encontrado: WASD move, botões do mouse atacam, Espaço pula. Todas as teclas podem ser trocadas." },
    tecladoAtajoMando: { tr: "Kumanda bağlı; klavye de aynı anda çalışır.", en: "A controller is connected; the keyboard works at the same time.", es: "Hay un mando conectado; el teclado funciona a la vez.", pt: "Há um controle conectado; o teclado funciona ao mesmo tempo." },
    tecladoAtajoBoton: { tr: "Klavye tuşları", en: "Keyboard keys", es: "Teclas del teclado", pt: "Teclas do teclado" },
    finAnticipado: { tr: "Kare sonunu öne al (Early FINISH)", en: "Finish frames early (Early FINISH)", es: "Adelantar el fin del cuadro (Early FINISH)", pt: "Antecipar o fim do quadro (Early FINISH)" },
    finAnticipadoDesc: { tr: "Oyun, VU1 bu kareyi çizerken sonrakini hazırlar: yoğun dövüşte yaklaşık %20 daha fazla FPS (ölçüldü). Görüntü hatası görürseniz kapatın.", en: "The game prepares the next frame while VU1 draws this one: about 20% more FPS in heavy combat (measured). Turn off if you see image glitches.", es: "El juego prepara el siguiente cuadro mientras VU1 dibuja este: cerca de un 20% más de FPS en combates intensos (medido). Desactívalo si ves fallos de imagen.", pt: "O jogo prepara o próximo quadro enquanto a VU1 desenha este: cerca de 20% mais FPS em combates pesados (medido). Desligue se notar falhas de imagem." },
    instPgoOn: { tr: "etkin", en: "active", es: "activa", pt: "ativa" },
    instPgoRec: { tr: "önerilir", en: "recommended", es: "recomendada", pt: "recomendada" },
    pgoRecomendado: { tr: "FPS optimizasyonu önerilir (PGO)", en: "FPS optimisation recommended (PGO)", es: "Optimización de FPS recomendada (PGO)", pt: "Otimização de FPS recomendada (PGO)" },
    cardImagen: { en: "Display", es: "Pantalla", pt: "Tela" },
    cardEscala: { en: "Internal resolution", es: "Resolución interna", pt: "Resolução interna" },
